FLAT_IP = [parse_range('JJ-77, AQs-ATs, KQs, KJs, QJs, JTs, T9s, AQo'),
           parse_range('TT-55, AQs-A9s, KTs+, QTs+, JTs, T9s, 98s, AQo-AJo, KQo'),
           parse_range('99-22, ATs-A6s, KTs+, QTs+, J9s+, T9s, 98s, 87s, 76s, AJo-ATo, KQo, KJo'),
           parse_range('99-22, ATs-A6s, KTs+, QTs+, J9s+, T9s, 98s, 87s, 76s, AJo-ATo, KQo, KJo')]
