ISO_EXTRA = parse_range('88+, ATs+, KJs+, AJo+, KQo')


def band_of(x):
    if x <= 0.17: return 0
    if x <= 0.26: return 1
    return 2


# ----------------------------------------------------------------------------- range math
NXG = len(XG)


def eqx(h, x):
    """equity of class h vs top-x (all-in order)."""
    row = EQR[h]
    if x <= XG[0]: return row[0] * 1e-4
    if x >= 1.0: return row[-1] * 1e-4
    j = bisect_left(XG, x)
    x0 = XG[j - 1]; x1 = XG[j]; t = (x - x0) / (x1 - x0)
    return (row[j - 1] * (1 - t) + row[j] * t) * 1e-4


def callwidth(J, q):
    """fraction of all hands with equity >= q vs top-J."""
    j = bisect_left(XG, J)
    if j >= NXG: j = NXG - 1
    i = int((q - QG0) * 100 + 0.5)
    if i < 0: i = 0
    if i > 50: return 0.0
    return CW[j][i]


def sg_index(s):
    j = bisect_left(SG, s)
    if j >= len(SG): return len(SG) - 1
    if j > 0 and s - SG[j - 1] < SG[j] - s: return j - 1
    return j


def push_x(k, s_bb):
    if k < 1: k = 1
    if k > 7: k = 7
    return PUSH[k][sg_index(s_bb)]


# ----------------------------------------------------------------------------- ICM (exact Harville, O(n))
PAY = (10, 7, 5, 4, 3, 2, 1, 0)


def icm(stk, h):
    """Harville ICM value of player h for payouts 10/7/5/4/3/2/1/0 (top places only; zeros allowed)."""
    sh = stk[h]
    if sh <= 0:
        others = 0
        for j, s in enumerate(stk):
            if j != h and s > 0: others += 1
        return PAY[others if others < 8 else 7]
    S = 0.0
    for s in stk: S += s
    lin = 0.0; p2 = 0.0
    for j, s in enumerate(stk):
        if j == h or s <= 0: continue
        lin += s / (sh + s)
        p2 += s * sh / (S * (S - s))
    return 7.0 - lin + 3.0 * sh / S + p2


# ----------------------------------------------------------------------------- postflop strength
def board_info(board):
    rs = sorted([c >> 2 for c in board], reverse=True)
    sc = [0, 0, 0, 0]
    for c in board: sc[c & 3] += 1
    mx_s = max(sc)
    u = sorted(set(rs), reverse=True)
    paired = len(u) < len(rs)
    wet = 0
    if mx_s >= 3: wet += 2
    elif mx_s == 2 and len(board) == 3: wet += 1
    # connectedness: most distinct ranks inside any 5-rank window (ace also low)
    m = 0
    for r in u: m |= 1 << (r + 1)
    if 12 in u: m |= 1
    conn = 0
    for lo in range(0, 10):
        b = BITS[(m >> lo) & 0b11111]
        if b > conn: conn = b
    if conn >= 2: wet += 1
    if conn >= 3: wet += 1
    if paired: wet -= 1
    return rs, u, mx_s, paired, wet


def strength(hole, board):
    """returns (hs, tier, draw_eq): hs ~ equity vs a continuing range."""
    cards = list(hole) + list(board)
    sc = eval7(cards); cat = sc >> 20
    nb = len(board)
    rs, u, mx_s, paired, wet = board_info(board)
    h1, h2 = hole[0] >> 2, hole[1] >> 2
    if h1 < h2: h1, h2 = h2, h1
    top = rs[0]
    pocket = h1 == h2
    tier = 0
    if cat >= 4:
        bsc = eval7(list(board)) if nb == 5 else -1
        if bsc >= 0 and bsc == sc:
            tier = 1  # playing the board
        else:
            tier = 5
            if cat == 4 and mx_s >= 3: tier = 4
            if cat == 5:
                # flush: is our flush card high?
                fs = -1
                cnt = [0, 0, 0, 0]
                for c in cards: cnt[c & 3] += 1
                for s in range(4):
                    if cnt[s] >= 5: fs = s
                hr = max([c >> 2 for c in hole if (c & 3) == fs] or [-1])
                bsuit = sum(1 for c in board if (c & 3) == fs)
                if bsuit >= 4 and hr < 10: tier = 4 if hr >= 7 else 3
            if cat >= 6 and paired and not pocket:
                # full house via board pair: need a hole card that matters
                if not ((h1 in rs) or (h2 in rs)): tier = 2
    elif cat == 3:
        if pocket and h1 in rs: tier = 5  # set
        elif h1 in rs or h2 in rs:
            kick = h2 if h1 in rs else h1
            tier = 5 if kick >= 10 else 4
        else:
            tier = 2 if h1 >= 11 else 1
    elif cat == 2:
        if not pocket and h1 in rs and h2 in rs and not paired:
            tier = 5 if (wet < 3 or nb == 3) else 4
        elif pocket:
            if h1 > top: tier = 4
            elif h1 > rs[1] if len(rs) > 1 else False: tier = 3
            else: tier = 2
        elif h1 in rs or h2 in rs:
            pr = h1 if h1 in rs else h2
            kick = h2 if pr == h1 else h1
            if pr == top: tier = 4 if kick >= 9 else 3
            else: tier = 2
        else:
            tier = 1 if h1 >= 11 else 0
    elif cat == 1:
        if pocket:
            if h1 > top: tier = 4
            elif len(u) > 1 and h1 > u[1]: tier = 3
            else: tier = 2
        elif h1 in rs or h2 in rs:
            pr = h1 if h1 in rs else h2
            kick = h2 if pr == h1 else h1
            if pr == top:
                tier = 4 if kick >= 9 or (pr == 12 and kick >= 7) else 3
            elif len(u) > 1 and pr == u[1]:
                tier = 3 if kick >= 11 else 2
            else:
                tier = 2
        else:
            tier = 1 if h1 >= 11 else 0
    else:
        tier = 1 if h1 == 12 else 0
    hs = (0.12, 0.27, 0.42, 0.58, 0.75, 0.92)[tier]
    if tier == 4 and wet >= 3: hs -= 0.05
    if tier == 3 and nb == 5: hs -= 0.03
    draw = 0.0
    if nb < 5:
        cnt = [0, 0, 0, 0]
        for c in cards: cnt[c & 3] += 1
        for s in range(4):
            if cnt[s] == 4 and ((hole[0] & 3) == s or (hole[1] & 3) == s) and cat < 5:
                draw = 0.36 if nb == 3 else 0.19
                hr = max([c >> 2 for c in hole if (c & 3) == s])
                if hr >= 11: draw += 0.04
        if cat < 4:
            m = 0; bm = 0
            for c in cards: m |= 1 << (c >> 2)
            for c in board: bm |= 1 << (c >> 2)
            outs = 0
            for r in range(13):
                if not (m >> r & 1):
                    if STRAIGHT[m | (1 << r)] >= 0 and STRAIGHT[bm | (1 << r)] < 0: outs += 1
            if outs >= 2: sd = 0.32 if nb == 3 else 0.17
            elif outs == 1: sd = 0.17 if nb == 3 else 0.09
            else: sd = 0.0
            if sd:
                draw = draw + sd * (0.6 if draw else 1.0)
        if tier <= 1 and nb == 3 and h2 > top: draw += 0.08  # two overcards
    if draw:
        hs = 1.0 - (1.0 - hs) * (1.0 - draw)
    return hs, tier, draw, wet


# ----------------------------------------------------------------------------- the bot
class Bot(Agent):
    def __init__(self):
        self.rng = random.Random(1)
        self.seat = 0; self.n = 8
        self._reset_stats(8)

    def _reset_stats(self, n):
        self.n = n
        self.s_hands = [0] * n; self.s_raise = [0] * n; self.s_jam = [0] * n
        self.s_pact = [0] * n; self.s_pagg = [0] * n; self.s_pfold = [0] * n
        self.cur_hand = None; self.seen = 0; self.seen_street = 0
        self.p_seen = set(); self.p_raise = set(); self.p_jam = set()
        self.my_last = {}  # street -> my last action kind

    def new_table(self, rules, seat, n_players):
        try:
            n = int(n_players) if n_players else 8
        except Exception:
            n = 8
        if n < 2 or n > 12: n = 8
        self.seat = seat if isinstance(seat, int) else 0
        self.rng = random.Random(1000003 * (self.seat + 1) + 7919)
        self._reset_stats(max(n, 8))

    def hand_end(self, result):
        try:
            self._commit()
        except Exception:
            pass

    # ------------------------------------------------------------------ stats
    def _commit(self):
        for s in self.p_seen:
            if s < self.n:
                self.s_hands[s] += 1
                if s in self.p_raise: self.s_raise[s] += 1
                if s in self.p_jam: self.s_jam[s] += 1
        self.p_seen = set(); self.p_raise = set(); self.p_jam = set()

    def _observe(self, o, bb):
        if o.hand_no != self.cur_hand:
            self._commit()
            self.cur_hand = o.hand_no; self.seen = 0; self.seen_street = o.street; self.my_last = {}
        hist = o.history or []
        if o.street != self.seen_street:
            # entries since our last act span streets: skip them for stats
            self.seen = len(hist); self.seen_street = o.street
            return
        me = o.seat
        for idx in range(self.seen, len(hist)):
            try:
                s, a = hist[idx]; kind = a[0]; amt = a[1] if len(a) > 1 else 0
            except Exception:
                continue
            if s == me or not isinstance(s, int) or s < 0 or s >= self.n: continue
            if o.street == 0:
                if kind in ('raise', 'call', 'fold', 'check'):
                    if kind == 'raise' and amt <= bb: continue
                    self.p_seen.add(s)
                    if kind == 'raise':
                        self.p_raise.add(s)
                        if s < len(o.stacks) and amt >= 0.45 * (o.stacks[s] + amt): self.p_jam.add(s)
            else:
                if kind in ('raise', 'call', 'fold', 'check'):
                    self.s_pact[s] += 1
                    if kind == 'raise': self.s_pagg[s] += 1
                    elif kind == 'fold': self.s_pfold[s] += 1
        self.seen = len(hist)

    def raise_rate(self, s):
        if s is None or s >= self.n or not self.reads_pre: return 0.18
        return (self.s_raise[s] + 0.18 * 12) / (self.s_hands[s] + 12)

    def jam_rate(self, s):
        if s is None or s >= self.n or not self.reads_pre: return 0.05
        return (self.s_jam[s] + 0.05 * 12) / (self.s_hands[s] + 12)

    def fold_rate(self, s):
        if s is None or s >= self.n or not self.reads_post: return 0.3
        return (self.s_pfold[s] + 0.3 * 8) / (self.s_pact[s] + 8)

    def agg_rate(self, s):
        if s is None or s >= self.n or not self.reads_post: return 0.3
        return (self.s_pagg[s] + 0.3 * 8) / (self.s_pact[s] + 8)

    # ------------------------------------------------------------------ helpers
    def _raise(self, o, amt):
        if 'raise' not in o.legal:
            if 'call' in o.legal: return ('call', 0)
            return ('check', 0)
        amt = int(amt)
        lo = int(o.min_raise); hi = int(o.max_raise)
        if amt < lo: amt = lo
        if amt > hi: amt = hi
        if hi - amt < 0.2 * amt: amt = hi
        return ('raise', amt)

    def _passive(self, o):
        if 'check' in o.legal: return ('check', 0)
        return ('fold', 0)

    def _call(self, o):
        if 'call' in o.legal: return ('call', 0)
        if 'check' in o.legal: return ('check', 0)
        return ('fold', 0)

    def act(self, o):
        try:
            return self._act(o)
        except Exception:
            try:
                return self._passive(o)
            except Exception:
                return ('fold', 0)

    def _act(self, o):
        bb = o.blinds[1] if o.blinds and o.blinds[1] else 20
        self._observe(o, bb)
        if o.street == 0:
            a = self._preflop(o, bb)
        else:
            a = self._postflop(o, bb)
        if a[0] not in o.legal:
            a = self._passive(o) if a[0] != 'raise' else self._call(o)
        self.my_last[o.street] = a[0]
        return a

    # ------------------------------------------------------------------ preflop
    def _positions(self, o):
        n = len(o.stacks); st = o.stacks; bets = o.bets; ih = o.in_hand
        alive = [i for i in range(n) if st[i] > 0 or bets[i] > 0 or ih[i]]
        btn = o.button if isinstance(o.button, int) else 0
        def nxt(s):
            for d in range(1, n + 1):
                j = (s + d) % n
                if j in alive: return j
            return s
        if len(alive) == 2:
            sb = btn if btn in alive else nxt(btn); bbs = nxt(sb)
        else:
            sb = nxt(btn); bbs = nxt(sb)
        order = []; s = bbs
        for _ in range(len(alive)):
            s = nxt(s); order.append(s)
        return alive, sb, bbs, order

    def _val(self, stk, h):
        w = self.icm_w
        if w >= 1.0: return icm(stk, h)
        S = 0
        for x in stk: S += x
        lin = 32.0 * stk[h] / S if S > 0 else 0.0
        if w <= 0.0: return lin
        return w * icm(stk, h) + (1.0 - w) * lin

    def _icm_stacks(self, o):
        # chips at hand start (preflop): stack + bets
        return [o.stacks[i] + o.bets[i] for i in range(len(o.stacks))]

    def _allin_ev(self, o, h, T, responders, J, eq_override=None):
        """EV (ICM) of hero putting T[h] in now. responders: list of (seat, range_width). J: our perceived range."""
        me = o.seat; n = len(T); bets = o.bets
        pot = 0
        for b in bets: pot += b
        base = list(o.stacks)
        # everyone folds
        fin = list(base); fin[me] = base[me] + pot
        pnone = 1.0; ev = 0.0
        for (i, x) in responders:
            if pnone < 1e-4: break
            m = T[me] if T[me] < T[i] else T[i]
            dead = pot - bets[me] - bets[i]
            need = m - bets[i]
            if need <= 0:
                pc = 1.0; c = x
            else:
                q = need / float(2 * m + dead)
                c = callwidth(J, q)
                if c > x: c = x
                pc = c / x if x > 0 else 0.0
                if c <= 0: continue
            e = eq_override if eq_override is not None else eqx(h, c if c > 0.005 else 0.005)
            w = list(base); w[me] = T[me] + m + dead; w[i] = T[i] - m
            l = list(base); l[me] = T[me] - m; l[i] = T[i] + m + dead
            ev += pnone * pc * (e * self._val(w, me) + (1 - e) * self._val(l, me))
            pnone *= (1 - pc)
        ev += pnone * self._val(fin, me)
        return ev

    def _fold_value(self, o, winner):
        fin = list(o.stacks)
        pot = 0
        for b in o.bets: pot += b
        if winner is not None: fin[winner] += pot
        return self._val(fin, o.seat)

    def _call_allin_ev(self, o, h, T, opps_x, eq_mult=1.0):
        """hero calls (all-in or committing) vs opponents already in with range widths. Single main villain."""
        me = o.seat; bets = o.bets
        pot = 0
        for b in bets: pot += b
        # main villain = biggest committed
        e = 1.0
        for (i, x) in opps_x:
            e *= eqx(h, x)
        if len(opps_x) > 1: e = e ** 0.85
        e *= eq_mult
        base = list(o.stacks)
        mine = T[me]
        vbig = 0
        for (i, x) in opps_x:
            if T[i] > vbig: vbig = T[i]
        ours = mine if mine < vbig else vbig
        win = list(base); lose = list(base)
        tot_win = 0
        for i in range(len(T)):
            if i == me: continue
            contrib = bets[i]
            if any(i == j for j, _ in opps_x):
                contrib = T[i] if T[i] < mine else mine
                if contrib < bets[i]: contrib = bets[i]
                lose[i] = T[i] - contrib
                win[i] = T[i] - contrib
            tot_win += contrib if contrib < mine or any(i == j for j, _ in opps_x) else mine
        win[me] = mine + tot_win
        lose[me] = mine - ours
        # give lost pot to the biggest villain
        vmax = max(opps_x, key=lambda t: T[t[0]])[0]
        lose[vmax] += tot_win + ours
        # note: chips counted for win/lose stacks approximate side pots
        return e * self._val(win, me) + (1 - e) * self._val(lose, me)

    def _preflop(self, o, bb):
        me = o.seat; n = len(o.stacks)
        h = cls_of(o.hole[0], o.hole[1]); pct = PCT[h]
        alive, sb, bbs, order = self._positions(o)
        T = self._icm_stacks(o)
        mx = max(o.bets)
        hist = o.history or []
        raises = []
        for ent in hist:
            try:
                s, a = ent
                if a[0] == 'raise' and a[1] > bb and isinstance(s, int) and 0 <= s < n and s != me:
                    raises.append((s, a[1]))
            except Exception:
                pass
        if mx > bb and (not raises or o.bets[raises[-1][0]] < mx):
            top = [i for i in range(n) if o.bets[i] == mx and i != me]
            if top: raises.append((top[0], mx))
        my_idx = order.index(me) if me in order else len(order) - 1
        behind = [s for s in order[my_idx + 1:] if o.in_hand[s] and s != me]
        k = len(behind)
        mystack = T[me]
        to_call = o.to_call
        ip_pos = k  # players behind
        # ---------------- unopened (maybe limpers)
        if mx <= bb and not [r for r in raises if r[1] > bb]:
            limpers = [s for s in alive if s != me and o.bets[s] >= bb and s != bbs and o.in_hand[s]]
            if me == bbs and to_call == 0:
                # option: raise strong hands for value
                if not limpers and o.bets[sb] < bb:
                    return ('check', 0)
                if pct <= 0.10 or (pct <= 0.16 and len(limpers) <= 1):
                    eff = min(mystack, max([T[s] for s in alive if s != me and o.in_hand[s]] or [mystack])) / float(bb)
                    if eff <= 12: return self._raise(o, o.max_raise)
                    return self._raise(o, mx + (3 + len(limpers)) * bb)
                return ('check', 0)
            opp_max = max([T[s] for s in behind] or [0])
            eff = min(mystack, opp_max) / float(bb) if behind else mystack / float(bb)
            pf_limit = self.pf_late if k <= 2 else self.pf_early
            if eff <= pf_limit:
                kk = k + len(limpers) // 2
                J = push_x(kk, eff)
                chart = pct <= J * self.push_mult
                if self.mode_push == 'chart':
                    go = chart
                else:
                    # ICM check on the chart decision
                    resp = [(s, 1.0) for s in behind] + [(s, 0.35) for s in limpers if s not in behind]
                    ev_j = self._allin_ev(o, h, T, resp, J)
                    ev_f = self._fold_value(o, bbs)
                    if self.mode_push == 'icm': go = ev_j > ev_f
                    else: go = chart and ev_j > ev_f - self.icm_tol
                if go:
                    return self._raise(o, o.max_raise)
                return self._passive(o)
            # standard open / iso
            kk = k if k <= 7 else 7
            if kk < 1: kk = 1
            rng = OPEN[kk]
            if limpers:
                if h in ISO_EXTRA or (h in rng and pct <= 0.12):
                    return self._raise(o, (3 + len(limpers)) * bb + o.bets[me] * 0)
                if me == sb and h in OPEN[min(7, kk + 2)]:
                    return self._call(o)
                return self._passive(o)
            if h in rng:
                if me == sb: size = 3.0 if eff >= 40 else 2.5
                else: size = 2.5 if eff >= 40 else (2.2 if eff >= 25 else 2.0)
                return self._raise(o, int(size * bb))
            return self._passive(o)
        # ---------------- facing raise(s)
        if not raises:  # inconsistent observation (e.g. we are the top bet): play it safe
            if to_call == 0: return ('check', 0)
            return self._call(o) if pct <= 0.08 else self._passive(o)
        nr = len(raises)
        last_r, last_amt = raises[-1]
        rs = last_r
        r_idx = order.index(rs) if rs in order else 0
        k_r = len(order) - 1 - r_idx
        allin_r = o.stacks[rs] == 0 if rs < n else False
        T_r = T[rs]
        committed_r = o.bets[rs] >= 0.45 * T_r
        eff = min(mystack, T_r) / float(bb)
        # estimate raiser range width
        if nr == 1:
            if allin_r or committed_r:
                x_r = push_x(k_r, T_r / float(bb)) if T_r / float(bb) <= 30 else 0.06
                x_r = max(x_r, min(1.0, self.jam_rate(rs) * 1.3))
            else:
                x_r = OPENW.get(min(7, max(1, k_r)), 0.2)
                x_r = max(x_r, min(1.0, self.raise_rate(rs) * 1.1))
        elif nr == 2:
            x_r = 0.07 if not (allin_r or committed_r) else 0.10
            x_r = max(x_r, min(1.0, self.raise_rate(rs) * 0.6), min(1.0, self.jam_rate(rs) * 1.3))
        else:
            x_r = 0.035
            x_r = max(x_r, min(1.0, self.jam_rate(rs) * 1.0))
        my_in = o.bets[me]
        # others committed (callers / all-ins) besides raiser
        others_in = [s for s in alive if s != me and s != rs and o.in_hand[s] and o.bets[s] > bb]
        allin_others = [s for s in others_in if o.stacks[s] == 0]
        # ---- jam or commit decisions
        big = to_call >= 0.35 * (o.stacks[me]) or allin_r or committed_r or eff <= 25 or my_in >= 0.3 * mystack
        if big:
            # option A: call/jam vs raiser all-in or committed
            if allin_r or committed_r or to_call >= 0.5 * o.stacks[me]:
                opps = [(rs, x_r)] + [(s, min(x_r, 0.15)) for s in others_in]
                ev_c = self._call_allin_ev(o, h, T, opps)
                if behind: ev_c -= self.behind_pen * len(behind)  # overcall/squeeze risk behind
                ev_f = self._fold_value(o, rs)
                if ev_c > ev_f:
                    if 'raise' in o.legal and o.max_raise > mx and not allin_r and not allin_others:
                        return self._raise(o, o.max_raise)
                    return self._call(o)
                return self._passive(o)
            # option B: reshove over a non-committed raise (stack <= 25bb or deep enough to matter)
            if eff <= 25 or my_in >= 0.3 * mystack:
                J = max(0.04, min(0.30, 0.5 * x_r))
                resp = [(rs, x_r)] + [(s, 0.25) for s in others_in] + [(s, 1.0) for s in behind]
                ev_j = self._allin_ev(o, h, T, resp, J)
                winner = rs
                ev_f = self._fold_value(o, winner)
                if ev_j > ev_f and (pct <= max(0.025, 0.65 * x_r) or ev_j > ev_f + 0.02):
                    return self._raise(o, o.max_raise)
                # BB flat with good price
                if me == bbs and nr == 1 and to_call <= 1.6 * bb and eff >= 10:
                    bw = BB_DEF[3 if rs == sb else band_of(x_r)]
                    if h in bw and pct <= 0.6: return self._call(o)
                return self._passive(o)
        # ---- deep play
        if nr == 1:
            b = 3 if rs == sb else band_of(x_r)
            if x_r > 0.5: b = 2
            val = TB_VAL[b]; blf = TB_BLF[b]
            if h in val or (h in blf and eff >= 40 and self.rng.random() < 0.5):
                ip = me != sb and me != bbs
                size = (3.0 if ip else 3.8) * last_amt + bb * len(others_in)
                if size >= 0.4 * mystack: return self._raise(o, o.max_raise)
                return self._raise(o, size)
            if me == bbs:
                bw = BB_DEF[b if rs != sb else 3]
                if h in bw and to_call <= 2.5 * bb: return self._call(o)
                if h in FLAT_IP[b] and to_call <= 3.5 * bb: return self._call(o)
                return self._passive(o)
            if me == sb:
                if h in FLAT_IP[min(b, 1)] and pct <= 0.10 and to_call <= 3 * bb: return self._call(o)
                return self._passive(o)
            if h in FLAT_IP[b] and to_call <= 4 * bb + bb * len(others_in): return self._call(o)
            return self._passive(o)
        if nr == 2:
            if h in FOURBET:
                size = 2.3 * last_amt
                if size >= 0.4 * mystack: return self._raise(o, o.max_raise)
                return self._raise(o, size)
            if h in CALL3B_IP and eff >= 40 and to_call <= 0.15 * mystack and me != sb:
                return self._call(o)
            return self._passive(o)
        # 4-bet+
        if pct <= 0.02 or h in (12 * 13 + 12, 11 * 13 + 11):
            return self._raise(o, o.max_raise)
        if h in FOURBET and to_call <= 0.3 * mystack:
            return self._call(o)
        return self._passive(o)

    # ------------------------------------------------------------------ postflop
    def _postflop(self, o, bb):
        me = o.seat
        hs, tier, draw, wet = strength(o.hole, o.board)
        pot_total = o.pot + sum(o.bets)
        opps = [i for i in range(len(o.stacks)) if o.in_hand[i] and i != me]
        nopp = len(opps)
        mystack = o.stacks[me]
        street = o.street
        to_call = o.to_call
        rng = self.rng
        aggr = self.my_last.get(street - 1) == 'raise'
        actable = [i for i in opps if o.stacks[i] > 0]
        if to_call == 0:
            if not actable:
                return ('check', 0)
            # betting decision
            bet = None
            fr = min([self.fold_rate(i) for i in opps] or [0.3])
            station = fr < 0.12
            if street == 1:
                small = wet <= 1  # dry: rainbow/unconnected or paired
                frac = 0.33 if small else 0.66
                if tier >= 4: p = 0.9 if nopp == 1 else 1.0
                elif tier == 3: p = (0.8 if small else 0.5) if aggr else 0.25
                elif draw >= 0.15: p = 0.8 if aggr else 0.4
                elif tier == 2: p = (0.5 if small else 0.2) if aggr else 0.0
                else: p = (0.65 if small else 0.3) if aggr else 0.1
                if nopp >= 2:
                    if tier < 4: p *= 0.35 if draw < 0.3 else 0.7
                if tier >= 5 and small and nopp == 1 and rng.random() < 0.2: p = 0.0
                if rng.random() < p: bet = frac
            elif street == 2:
                if tier >= 4: p = 1.0
                elif tier == 3: p = 0.35 if aggr and nopp == 1 else 0.1
                elif draw >= 0.15: p = 0.5 if aggr else 0.25
                elif tier <= 1: p = 0.3 if aggr and nopp == 1 else 0.05
                else: p = 0.0
                if nopp >= 2 and tier < 4: p *= 0.3
                if rng.random() < p: bet = 0.66
            else:
                if tier >= 4: p = 1.0 if tier >= 5 else 0.75
                elif tier <= 1: p = 0.3 if aggr and nopp == 1 else 0.06
                else: p = 0.0
                if nopp >= 2 and tier < 4: p = 0.0
                if rng.random() < p: bet = 0.7
            if bet is not None and tier <= 2 and self.bluff_mult != 1.0 and rng.random() > self.bluff_mult:
                bet = None
            if station and bet is not None and tier <= 2 and draw < 0.15:
                bet = None  # obvious read: no bluffs into players who never fold
            if station and bet is None and tier == 3 and street < 3 and rng.random() < 0.5:
                bet = 0.5  # thin value vs stations
            if bet is None:
                return ('check', 0)
            amt = int(bet * pot_total)
            if amt < bb: amt = bb
            if amt >= 0.6 * mystack:
                if tier >= 3 or draw >= 0.3: return self._raise(o, o.max_raise)
                return ('check', 0)
            return self._raise(o, max(o.bets) + amt)
        # facing a bet
        bettor = max(opps, key=lambda i: o.bets[i]) if opps else None
        p0 = pot_total - to_call
        if p0 < 1: p0 = 1
        f = to_call / float(p0)
        q = to_call / float(pot_total + to_call)
        shift = 0.12 if street < 3 else 0.17
        shift += 0.04 * (nopp - 1) + self.call_shift
        if o.bets[me] > 0: shift += self.raised_shift  # we bet and got raised
        if bettor is not None:
            ar = self.agg_rate(bettor)
            if ar > 0.45: shift -= min(0.15, (ar - 0.45) * 0.5)
        e = hs - shift
        allin = to_call >= 0.5 * mystack
        if allin:
            # all-in style decision, ICM
            ev_c = self._post_allin_ev(o, e, bettor)
            ev_f = self._fold_value(o, bettor)
            if ev_c > ev_f:
                if 'raise' in o.legal and tier >= 4: return self._raise(o, o.max_raise)
                return self._call(o)
            return self._passive(o)
        # raises for value / semi-bluff
        if 'raise' in o.legal:
            if tier >= 5 or (tier >= 4 and street == 1 and nopp == 1 and f <= 0.5 and rng.random() < 0.3):
                amt = max(o.bets) * 3 + (pot_total - sum(o.bets))
                if amt >= 0.5 * (mystack + o.bets[me]): return self._raise(o, o.max_raise)
                return self._raise(o, amt)
            if street == 1 and draw >= 0.3 and nopp == 1 and rng.random() < 0.2:
                amt = max(o.bets) * 3 + (pot_total - sum(o.bets))
                if amt < 0.4 * (mystack + o.bets[me]): return self._raise(o, amt)
        implied = 0.06 if (draw and street < 3 and mystack > 3 * to_call) else 0.0
        if e >= q or (draw and draw + implied >= q):
            return self._call(o)
        # MDF-style floats: small bets in position with some equity
        if street == 1 and f <= 0.4 and nopp == 1 and hs >= 0.25 and rng.random() < 0.35:
            return self._call(o)
        return self._passive(o)

    def _post_allin_ev(self, o, e, villain):
        me = o.seat
        mine = o.stacks[me] + o.bets[me]
        base = list(o.stacks)
        if e < 0: e = 0.0
        if e > 1: e = 1.0
        pot_prev = o.pot
        # capped contributions this street
        cap = mine
        street_pot = 0
        for i in range(len(o.bets)):
            b = o.bets[i]
            street_pot += b if b < cap else cap
        total = pot_prev + street_pot
        win = list(base); lose = list(base)
        call_amt = mine - o.bets[me]
        win[me] = base[me] - call_amt + total if base[me] - call_amt + total > 0 else 0
        lose[me] = base[me] - call_amt
        if villain is not None:
            excess = o.bets[villain] - cap if o.bets[villain] > cap else 0
            win[villain] = base[villain] + excess
            lose[villain] = base[villain] + excess + total
        return e * self._val(win, me) + (1 - e) * self._val(lose, me)

    mode_push = 'chart'
    icm_w = 1.0
    icm_tol = 0.0
    pf_late = 12
    pf_early = 10
    push_mult = 1.0
    call_shift = 0.05
    bluff_mult = 0.6
    reads_pre = False
    reads_post = True
    raised_shift = 0.0
    behind_pen = 0.05
